 {
  "turns": [
    {
      "speaker": "customer",
      "text": "Hello? Mera phone kaam nahi kar raha hai, I am very frustrated with this service!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Welcome to Nimbus Telecom, I am Lucy. How can I help you?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Listen, mera device completely dead hai. I have tried everything, but it is not turning on. Bahut problem ho rahi hai!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Tell me your name and phone number.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My name is Vivek Khan and my number is 99349 80388.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I see your account. What is the exact issue with the device?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Screen black hai and charging nahi ho rahi. I paid a lot for this phone, yeh toh bilkul bekar hai!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Provide your address for the record.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is 387 Station Road.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The device is under warranty, but I cannot fix this over the phone.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Toh main kya karoon? Please help me, I need my phone for work!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am escalating this to the technical hardware team for a deeper look.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Thank you so much, I am glad you are taking care of it. Shukriya!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will book a device check for you at the nearest center.",
      "tags": [
        "action:device_fix"
      ]
    }
  ]
}
